//! PSLCORE — the Public Suffix List (<https://publicsuffix.org/list/>) and the two questions the web asks of
//! it: what is the PUBLIC SUFFIX of a host (`co.uk`, `github.io`), and what is its REGISTRABLE DOMAIN (the
//! public suffix plus one label: `example.co.uk`) — the "site" of HTML §7.1.2, the cache's network partition
//! key (Fetch §2.7.11), the cookie jar's public-suffix refusal (RFC 6265bis §5.7).
//!
//! `no_std`, no allocation: every answer is a slice of the host passed in. The rules are [`table::RULES`],
//! generated by `tools/gen_psl.py` from `public_suffix_list.dat` (ICANN and PRIVATE sections both, as browsers
//! use them), keyed by the rule with its `*.` / `!` removed, in ASCII (A-label) form.
//!
//! The algorithm (the list's "Formal algorithm"), over the host's labels right to left:
//! * a NORMAL rule matches when it equals a suffix of the host (whole labels);
//! * a WILDCARD rule `*.k` matches the suffix of one more label than `k`;
//! * an EXCEPTION rule `!k` matching the host makes the public suffix `k` without its leftmost label, and
//!   prevails over every other rule;
//! * otherwise the matching rule with the most labels prevails; when none matches, the rule is `*` (the
//!   host's last label is its public suffix).
//!
//! Hosts are expected as the WHATWG URL host parser leaves them: lowercase ASCII, U-labels already in
//! `xn--` form. One trailing dot (a fully-qualified name) is ignored. An IP address (IPv4 dotted-quad or a
//! bracketed IPv6 literal) has no public suffix and is its own site.

#![no_std]
#![forbid(unsafe_code)]

pub mod table;

use table::{EXCEPT, NORMAL, PRIVATE, RULES, WILD};

/// Which sections of the list apply.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Sections {
    /// ICANN and PRIVATE (`github.io` is a public suffix) — what browsers use for sites and cookies.
    All,
    /// The ICANN section only (`github.io` is a registrable domain under `io`).
    IcannOnly,
}

/// The flags of `key` in the table under `sections` (0 when absent).
fn lookup(key: &str, sections: Sections) -> u8 {
    match RULES.binary_search_by(|(k, _)| k.as_bytes().cmp(key.as_bytes())) {
        Ok(i) => {
            let f = RULES[i].1;
            if sections == Sections::IcannOnly && f & PRIVATE != 0 { 0 } else { f }
        }
        Err(_) => 0,
    }
}

/// An IPv4 dotted-quad (the URL parser's canonical form) or a bracketed IPv6 literal.
pub fn is_ip(host: &str) -> bool {
    if host.starts_with('[') {
        return true;
    }
    let mut parts = 0;
    for p in host.split('.') {
        parts += 1;
        if p.is_empty() || p.len() > 3 || !p.bytes().all(|b| b.is_ascii_digit()) || p.parse::<u16>().map_or(true, |v| v > 255) {
            return false;
        }
    }
    parts == 4
}

fn strip_dot(host: &str) -> &str {
    host.strip_suffix('.').unwrap_or(host)
}

/// The public suffix of `host` under `sections`, as a slice of it (without a trailing dot). `None` for an IP
/// address, an empty host, or one with an empty label.
pub fn public_suffix_with(host: &str, sections: Sections) -> Option<&str> {
    let h = strip_dot(host);
    if h.is_empty() || is_ip(h) || h.split('.').any(str::is_empty) {
        return None;
    }
    // Suffixes shortest first: the last label, then the last two, …
    let mut best: &str = &h[h.rfind('.').map_or(0, |i| i + 1)..]; // the implicit `*` rule
    let mut best_labels = 1usize;
    let mut end = h.len();
    let mut labels = 0usize;
    // `prev` is the suffix one label shorter than `s` (the base a wildcard `*.prev` names).
    let mut prev: Option<&str> = None;
    loop {
        let start = h[..end].rfind('.').map_or(0, |i| i + 1);
        let s = &h[start..];
        labels += 1;
        let f = lookup(s, sections);
        if f & EXCEPT != 0 {
            // `!s`: the public suffix is `s` without its leftmost label (`prev`).
            return prev.or(Some(s));
        }
        if f & NORMAL != 0 && labels >= best_labels {
            best = s;
            best_labels = labels;
        }
        if let Some(p) = prev {
            if lookup(p, sections) & WILD != 0 && labels >= best_labels {
                best = s;
                best_labels = labels;
            }
        }
        if start == 0 {
            break;
        }
        prev = Some(s);
        end = start - 1;
    }
    Some(best)
}

/// The public suffix of `host` (ICANN and PRIVATE rules).
pub fn public_suffix(host: &str) -> Option<&str> {
    public_suffix_with(host, Sections::All)
}

/// Is `host` itself a public suffix (so nothing can be registered as it, and a cookie may not be scoped to it)?
pub fn is_public_suffix(host: &str) -> bool {
    public_suffix(host).is_some_and(|s| s.len() == strip_dot(host).len())
}

/// The registrable domain of `host` under `sections`: its public suffix plus the label before it, as a slice
/// of `host` (without a trailing dot). `None` for an IP address, a malformed host, or a host that IS a public
/// suffix.
pub fn registrable_domain_with(host: &str, sections: Sections) -> Option<&str> {
    let h = strip_dot(host);
    let ps = public_suffix_with(h, sections)?;
    if ps.len() >= h.len() {
        return None;
    }
    let head = &h[..h.len() - ps.len() - 1]; // the labels before the suffix, without the joining dot
    let start = head.rfind('.').map_or(0, |i| i + 1);
    Some(&h[start..])
}

/// The registrable domain of `host` (ICANN and PRIVATE rules) — HTML's "site" for a domain host.
pub fn registrable_domain(host: &str) -> Option<&str> {
    registrable_domain_with(host, Sections::All)
}

/// The host a site is keyed by: the registrable domain, or the host itself when it has none (an IP address,
/// `localhost`, a host that is a public suffix) — HTML §7.1.2 "obtain a site" for a tuple origin's host.
pub fn site_host(host: &str) -> &str {
    registrable_domain(host).unwrap_or(strip_dot(host))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_list_s_own_examples() {
        // https://github.com/publicsuffix/list/blob/main/tests/test_psl.txt (a selection).
        assert_eq!(registrable_domain("com"), None);
        assert_eq!(registrable_domain("example.com"), Some("example.com"));
        assert_eq!(registrable_domain("www.example.com"), Some("example.com"));
        assert_eq!(registrable_domain("uk.com"), None);
        assert_eq!(registrable_domain("example.uk.com"), Some("example.uk.com"));
        assert_eq!(registrable_domain("b.example.uk.com"), Some("example.uk.com"));
        assert_eq!(registrable_domain("a.b.example.uk.com"), Some("example.uk.com"));
        assert_eq!(registrable_domain("test.ac"), Some("test.ac"));
        assert_eq!(registrable_domain("mm"), None);
        assert_eq!(registrable_domain("c.mm"), None);
        assert_eq!(registrable_domain("b.c.mm"), Some("b.c.mm"));
        assert_eq!(registrable_domain("a.b.c.mm"), Some("b.c.mm"));
        assert_eq!(registrable_domain("jp"), None);
        assert_eq!(registrable_domain("test.jp"), Some("test.jp"));
        assert_eq!(registrable_domain("www.test.jp"), Some("test.jp"));
        assert_eq!(registrable_domain("ac.jp"), None);
        assert_eq!(registrable_domain("test.ac.jp"), Some("test.ac.jp"));
        assert_eq!(registrable_domain("kyoto.jp"), None);
        assert_eq!(registrable_domain("test.kyoto.jp"), Some("test.kyoto.jp"));
        assert_eq!(registrable_domain("ide.kyoto.jp"), None);
        assert_eq!(registrable_domain("b.ide.kyoto.jp"), Some("b.ide.kyoto.jp"));
        assert_eq!(registrable_domain("c.kobe.jp"), None);
        assert_eq!(registrable_domain("b.c.kobe.jp"), Some("b.c.kobe.jp"));
        assert_eq!(registrable_domain("city.kobe.jp"), Some("city.kobe.jp"));
        assert_eq!(registrable_domain("www.city.kobe.jp"), Some("city.kobe.jp"));
        assert_eq!(registrable_domain("ck"), None);
        assert_eq!(registrable_domain("test.ck"), None);
        assert_eq!(registrable_domain("b.test.ck"), Some("b.test.ck"));
        assert_eq!(registrable_domain("www.ck"), Some("www.ck"));
        assert_eq!(registrable_domain("www.www.ck"), Some("www.ck"));
        assert_eq!(registrable_domain("us"), None);
        assert_eq!(registrable_domain("test.us"), Some("test.us"));
        assert_eq!(registrable_domain("ak.us"), None);
        assert_eq!(registrable_domain("test.ak.us"), Some("test.ak.us"));
        assert_eq!(registrable_domain("k12.ak.us"), None);
        assert_eq!(registrable_domain("test.k12.ak.us"), Some("test.k12.ak.us"));
        assert_eq!(registrable_domain("xn--85x722f.com.cn"), Some("xn--85x722f.com.cn"));
        assert_eq!(registrable_domain("www.xn--85x722f.xn--55qx5d.cn"), Some("xn--85x722f.xn--55qx5d.cn"));
        assert_eq!(registrable_domain("xn--55qx5d.cn"), None);
    }

    #[test]
    fn private_section_and_ips() {
        assert_eq!(registrable_domain("user.github.io"), Some("user.github.io"));
        assert_eq!(registrable_domain_with("user.github.io", Sections::IcannOnly), Some("github.io"));
        assert!(is_public_suffix("github.io"));
        assert!(is_public_suffix("co.uk"));
        assert!(!is_public_suffix("example.co.uk"));
        assert_eq!(registrable_domain("192.168.0.1"), None);
        assert_eq!(site_host("192.168.0.1"), "192.168.0.1");
        assert_eq!(site_host("[::1]"), "[::1]");
        assert_eq!(site_host("localhost"), "localhost");
        assert_eq!(site_host("a.b.example.co.uk."), "example.co.uk");
        assert_eq!(public_suffix("a..b"), None);
    }
}
